function nameOf(p){return p?.name?.[lang]||p?.name?.uz||''}
function productSeoSlug(p,l=lang){return String(p?.name?.[l]||p?.name?.uz||p?.name?.ru||'mahsulot').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[ʻʼ‘’`´']/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,90)+'-'+Number(p?.id||0)}
function categoryById(id){return categories.find(c=>c.id===id)||{id:'x',icon:'🛍️',name:{uz:'Boshqa',ru:'Другое',en:'Other'}}}
function cartQty(id){return Number(cart.find(x=>Number(x.id)===Number(id))?.qty||0)}
function subtotal(){return cart.reduce((s,x)=>{const p=products.find(p=>Number(p.id)===Number(x.id));return s+(p?Number(p.price||0)*Number(x.qty||0):0)},0)}
function total(){return Math.max(0,subtotal()-Number(promo.discount||0))}

