function activeHeroSlides(){return (Array.isArray(settings.heroSlides)?settings.heroSlides:[]).filter(x=>x&&x.active!==false&&x.image).slice(0,5)}
function renderHeroSlider(){const box=$('#homeSlider'),track=$('#homeSliderTrack'),dots=$('#homeSliderDots');if(!box||!track||!dots)return;const slides=activeHeroSlides();if(!slides.length){box.classList.add('empty');return}box.classList.remove('empty');if(heroSlideIndex>=slides.length)heroSlideIndex=0;track.innerHTML=slides.map((x,i)=>`<div class="home-slide ${i===heroSlideIndex?'active':''}"><img src="${esc(x.image)}" alt="Parkent tumani tabiati ${i+1}" loading="${i===0?'eager':'lazy'}"></div>`).join('');dots.innerHTML=slides.map((x,i)=>`<button class="home-slider-dot ${i===heroSlideIndex?'active':''}" type="button" onclick="goHeroSlide(${i})" aria-label="${i+1}-slayd"></button>`).join('');const showNav=slides.length>1;$('#homeSliderPrev').style.display=showNav?'grid':'none';$('#homeSliderNext').style.display=showNav?'grid':'none';startHeroAutoplay()}
function goHeroSlide(i){const slides=activeHeroSlides();if(!slides.length)return;heroSlideIndex=(Number(i)+slides.length)%slides.length;$$('.home-slide').forEach((el,n)=>el.classList.toggle('active',n===heroSlideIndex));$$('.home-slider-dot').forEach((el,n)=>el.classList.toggle('active',n===heroSlideIndex));startHeroAutoplay()}
function shiftHeroSlide(d){goHeroSlide(heroSlideIndex+Number(d||0))}
function startHeroAutoplay(){if(heroSlideTimer)clearInterval(heroSlideTimer);const slides=activeHeroSlides();if(slides.length>1)heroSlideTimer=setInterval(()=>goHeroSlide(heroSlideIndex+1),5000)}


let parkentLeafletMap=null;
const PARKENT_RELATION_ID='5745823';
const PARKENT_FALLBACK=[
 [41.447,69.620],[41.455,69.661],[41.446,69.688],[41.461,69.721],[41.471,69.764],[41.457,69.817],[41.421,69.819],[41.395,69.806],[41.365,69.801],[41.342,69.820],[41.309,69.806],[41.287,69.788],[41.255,69.773],[41.225,69.746],[41.197,69.708],[41.176,69.673],[41.194,69.642],[41.224,69.627],[41.249,69.602],[41.279,69.590],[41.300,69.568],[41.331,69.570],[41.358,69.556],[41.386,69.568],[41.411,69.584],[41.429,69.604]
];
function initParkentBoundaryMap(){
 const el=$('#parkentBoundaryMap'); if(!el||parkentLeafletMap||typeof window.L==='undefined')return;
 parkentLeafletMap=L.map(el,{scrollWheelZoom:false,zoomControl:true,attributionControl:true});
 L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'}).addTo(parkentLeafletMap);
 const style={color:'#ef2d2d',weight:4,opacity:1,dashArray:'6 6',fillColor:'#46cf63',fillOpacity:.26};
 const label=L.divIcon({className:'parkent-map-label',html:'<b>Parkent tumani</b><span>BEPUL YETKAZIB BERISH</span>',iconSize:[180,56],iconAnchor:[90,28]});
 const useFallback=()=>{const layer=L.polygon(PARKENT_FALLBACK,style).addTo(parkentLeafletMap);parkentLeafletMap.fitBounds(layer.getBounds(),{padding:[22,22]});L.marker([41.30,69.68],{icon:label,interactive:false}).addTo(parkentLeafletMap);};
 fetch('https://nominatim.openstreetmap.org/lookup?osm_ids=R'+PARKENT_RELATION_ID+'&format=geojson&polygon_geojson=1',{headers:{'Accept':'application/geo+json,application/json'}})
  .then(r=>{if(!r.ok)throw new Error('boundary');return r.json()})
  .then(g=>{const features=g?.features||[];if(!features.length)throw new Error('empty');const layer=L.geoJSON(g,{style}).addTo(parkentLeafletMap);const bounds=layer.getBounds();if(!bounds.isValid())throw new Error('bounds');parkentLeafletMap.fitBounds(bounds,{padding:[22,22]});L.marker(bounds.getCenter(),{icon:label,interactive:false}).addTo(parkentLeafletMap)})
  .catch(useFallback);
 setTimeout(()=>parkentLeafletMap.invalidateSize(),200);
}

function formatPhone(p){const d=String(p).replace(/\D/g,'');if(d.length===12)return `+${d.slice(0,3)} ${d.slice(3,5)} ${d.slice(5,8)} ${d.slice(8,10)} ${d.slice(10)}`;return p}
function renderAll(){renderHeroSlider();renderCategories();renderProducts();renderCart();renderFavCount();}
function renderCategories(){const all=`<button class="category-pill ${filter==='all'?'active':''}" onclick="setFilter('all')"><b>${tr('all')}</b></button>`;const xs=categories.map(c=>`<button class="category-pill ${filter===c.id?'active':''}" onclick="setFilter('${esc(c.id)}')"><b>${esc(c.name?.[lang]||c.name?.uz||'')}</b></button>`).join('');$('#categoryStrip').innerHTML=all+xs;$('#categoryFilters').innerHTML=`<button class="filter ${filter==='all'?'active':''}" onclick="setFilter('all')">${tr('all')}</button>`+categories.map(c=>`<button class="filter ${filter===c.id?'active':''}" onclick="setFilter('${esc(c.id)}')">${esc(c.name?.[lang]||c.name?.uz||'')}</button>`).join('')}
function setFilter(v){filter=v;renderCategories();renderProducts();document.querySelector('#products').scrollIntoView({behavior:'smooth'});}
function productList(){let arr=products.filter(p=>(filter==='all'||p.cat===filter)&&(!search||nameOf(p).toLowerCase().includes(search.toLowerCase())||String(p.badge||'').toLowerCase().includes(search.toLowerCase())));if(sort==='priceAsc')arr.sort((a,b)=>a.price-b.price);else if(sort==='priceDesc')arr.sort((a,b)=>b.price-a.price);else if(sort==='new')arr.sort((a,b)=>Number(b.id)-Number(a.id));else arr.sort((a,b)=>Number(b.featured)-Number(a.featured));return arr}
function showSiteToast(message){const t=$('#siteToast');if(!t)return;t.textContent=message;t.classList.add('show');clearTimeout(window.__siteToastTimer);window.__siteToastTimer=setTimeout(()=>t.classList.remove('show'),1800)}
function updateCatalogMeta(count){const el=$('#productCountText'),clear=$('#clearCatalogFilters');if(el)el.textContent=tr('found',count);if(clear){clear.textContent=tr('clear');clear.hidden=!(filter!=='all'||String(search||'').trim())}}
function renderProducts(){const arr=productList();$('#productGrid').innerHTML=arr.length?arr.map(p=>{const q=qtyPick[p.id]||1,c=categoryById(p.cat),fav=favorites.includes(Number(p.id)),stock=Number(p.stock||0);return `<article class="product-card"><button class="fav-btn ${fav?'on':''}" onclick="toggleFav(${p.id})">${fav?'♥':'♡'}</button>${p.badge?`<span class="badge">${esc(p.badge)}</span>`:''}<div class="product-media ${p.image?'zoomable':''}" ${p.image?`onclick="openProductImage(${p.id})" role="button" tabindex="0" aria-label="${esc(nameOf(p))}"`:''}>${p.image?`<img src="${p.image}" alt="${esc(nameOf(p))}"><span class="zoom-hint">${tr('zoom')}</span>`:`<span class="no-image">${tr('no_image')}</span>`}</div><div class="product-body"><small>${esc(c.name?.[lang]||c.name?.uz||'')}</small><h3><a class="product-seo-link" href="${lang==='ru'?'/ru/mahsulot/':'/mahsulot/'}${productSeoSlug(p)}">${esc(nameOf(p))}</a></h3><div class="price-row"><div>${p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del>`:''}<b>${money(p.price)}</b></div><span>${tr('stock')}: ${stock}</span></div><div class="qty-add"><div class="stepper"><button onclick="pickQty(${p.id},-1)">−</button><b id="pick-${p.id}">${q}</b><button onclick="pickQty(${p.id},1)">+</button></div><button class="add-btn" ${stock<=0?'disabled':''} onclick="addToCart(${p.id})">${stock<=0?tr('out'):tr('add')}</button></div></div></article>`}).join(''):`<div class="empty-state request-empty"><h3>${tr('not_found')}</h3><p>${tr('not_found_sub')}</p><button class="btn primary" onclick="openProductRequest()">${tr('request')}</button></div>`;updateCatalogMeta(arr.length)}
function pickQty(id,d){const p=products.find(x=>Number(x.id)===Number(id));let q=Number(qtyPick[id]||1)+d;q=Math.max(1,Math.min(Number(p?.stock||1),q));qtyPick[id]=q;const el=document.getElementById('pick-'+id);if(el)el.textContent=q}
function addToCart(id){const p=products.find(x=>Number(x.id)===Number(id));if(!p)return;const add=Number(qtyPick[id]||1),found=cart.find(x=>Number(x.id)===Number(id)),next=(found?.qty||0)+add;if(next>Number(p.stock||0)){alert(tr('not_enough'));return}if(found)found.qty=next;else cart.push({id:Number(id),qty:add});qtyPick[id]=1;promo.discount=0;saveCart();renderCart();showSiteToast(tr('added'));openCart();renderProducts()}
function changeCart(id,d){const x=cart.find(x=>Number(x.id)===Number(id)),p=products.find(p=>Number(p.id)===Number(id));if(!x||!p)return;const q=x.qty+d;if(q<=0)cart=cart.filter(a=>Number(a.id)!==Number(id));else if(q<=Number(p.stock||0))x.qty=q;promo.discount=0;saveCart();renderCart();renderProducts()}
function removeCart(id){cart=cart.filter(a=>Number(a.id)!==Number(id));promo.discount=0;saveCart();renderCart();renderProducts()}
function renderCart(){const valid=cart.filter(x=>products.some(p=>Number(p.id)===Number(x.id)));cart=valid;saveCart();const count=cart.reduce((s,x)=>s+Number(x.qty||0),0);$('#cartCount').textContent=count;$('#cartSub').textContent=tr('items',count);$('#cartItems').innerHTML=cart.length?cart.map(x=>{const p=products.find(p=>Number(p.id)===Number(x.id));return `<div class="cart-line"><div class="cart-thumb">${p.image?`<img src="${p.image}">`:tr('no_image')}</div><div class="cart-info"><b>${esc(nameOf(p))}</b><span>${money(p.price)} × ${x.qty}</span><div class="mini-stepper"><button onclick="changeCart(${p.id},-1)">−</button><b>${x.qty}</b><button onclick="changeCart(${p.id},1)">+</button></div></div><div class="cart-price"><b>${money(p.price*x.qty)}</b><button onclick="removeCart(${p.id})">×</button></div></div>`}).join(''):`<div class="empty-cart"><b>${tr('empty_cart')}</b><span>${tr('empty_cart_sub')}</span></div>`;$('#cartSubtotal').textContent=money(subtotal());$('#cartDiscount').textContent='− '+money(promo.discount);$('#cartTotal').textContent=money(total());$('#mobileCartText').textContent=`${tr('cart')} • ${money(total())}`;$('#mobileStickyCart').classList.toggle('show',count>0)}
function openCart(){closeTracking();$('#cartPanel').classList.add('open');$('#overlay').classList.add('show')}
function closeCart(){$('#cartPanel').classList.remove('open');if(!$('#trackingPanel')?.classList.contains('open'))$('#overlay').classList.remove('show')}
function openTracking(){closeCart();$('#trackingPanel').classList.add('open');$('#overlay').classList.add('show')}
function closeTracking(){$('#trackingPanel')?.classList.remove('open');if(!$('#cartPanel')?.classList.contains('open'))$('#overlay').classList.remove('show')}
function closeSidePanels(){closeCart();closeTracking()}
async function applyPromo(){const code=$('#cartPromo').value.trim();if(!code){promo={code:'',discount:0};renderCart();return}try{const r=await fetch('/api/promo/validate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code,subtotal:subtotal()})});const d=await r.json();if(!r.ok)throw new Error(d.error);promo={code:d.code,discount:d.discount};renderCart();alert(`${tr('promo_ok')}: -${money(d.discount)}`)}catch(e){promo={code:'',discount:0};renderCart();alert(e.message)}}
function toggleFav(id){id=Number(id);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];saveFavs();renderFavCount();renderProducts()}
function renderFavCount(){$('#favCount').textContent=favorites.length}
function showFavorites(){if(!favorites.length){showModal(`<div class="modal-card"><button class="x" onclick="closeModal()">×</button><h2>♡ ${tr('fav')}</h2><p>${tr('no_favs')}</p></div>`);return}showModal(`<div class="modal-card wide"><button class="x" onclick="closeModal()">×</button><h2>♥ ${tr('fav')}</h2><div class="fav-list">${favorites.map(id=>{const p=products.find(x=>Number(x.id)===id);return p?`<div><span><b>${esc(nameOf(p))}</b></span><b>${money(p.price)}</b><button onclick="addToCart(${p.id});closeModal()">${tr('add')}</button></div>`:''}).join('')}</div></div>`)}
function openProductImage(id){const p=products.find(x=>Number(x.id)===Number(id));if(!p||!p.image)return;showModal(`<div class="modal-card image-lightbox"><button class="x" onclick="closeModal()" aria-label="Yopish">×</button><div class="lightbox-image-wrap"><img src="${p.image}" alt="${esc(nameOf(p))}"></div><div class="lightbox-info"><div><small>${esc(categoryById(p.cat).name?.[lang]||categoryById(p.cat).name?.uz||'')}</small><h2>${esc(nameOf(p))}</h2></div><div class="lightbox-price"><b>${money(p.price)}</b><span>${T[lang].stock}: ${Number(p.stock||0)}</span></div></div></div>`)}

function openProductRequest(){requestImage='';const searched=($('#searchInput')?.value||search||'').trim();const sets={uz:{ey:'MAXSUS SO‘ROV',title:'Kerakli mahsulotni topmadingizmi?',text:'Mahsulot nomi, miqdori va telefon raqamingizni kiriting. Xohlasangiz rasmini ham yuboring.',product:'Mahsulot nomi *',qty:'Miqdor *',size:'O‘lcham / Hajm',name:'Ismingiz',phone:'Telefon raqamingiz *',comment:'Qo‘shimcha ma’lumot',image:'Mahsulot rasmini qo‘shish (ixtiyoriy)',choose:'Fayl tanlash',send:'So‘rovni yuborish',example:'Masalan: Suyuq sovun 5 litr',sizeEx:'Masalan: 5 litr, 1 kg, 100 dona',detail:'Rang, brend, texnik xususiyatlar va h.k.',live:'So‘rovingiz admin panelga real vaqtda yetib boradi'},ru:{ey:'СПЕЦИАЛЬНЫЙ ЗАПРОС',title:'Не нашли нужный товар?',text:'Укажите товар, количество и телефон. При желании прикрепите фото.',product:'Название товара *',qty:'Количество *',size:'Размер / объём',name:'Ваше имя',phone:'Номер телефона *',comment:'Дополнительная информация',image:'Добавить фото товара (необязательно)',choose:'Выбрать файл',send:'Отправить запрос',example:'Например: Жидкое мыло 5 л',sizeEx:'Например: 5 л, 1 кг, 100 шт',detail:'Цвет, бренд, характеристики и т.д.',live:'Запрос поступит в админ-панель в реальном времени'},en:{ey:'SPECIAL REQUEST',title:'Can’t find the product you need?',text:'Enter the product, quantity and phone number. You may attach a photo.',product:'Product name *',qty:'Quantity *',size:'Size / volume',name:'Your name',phone:'Phone number *',comment:'Additional details',image:'Add product photo (optional)',choose:'Choose file',send:'Send request',example:'Example: Liquid soap 5 L',sizeEx:'Example: 5 L, 1 kg, 100 pcs',detail:'Color, brand, specifications, etc.',live:'Your request will reach the admin panel in real time'}};const x=sets[lang]||sets.uz;showModal(`<div class="modal-card request-card request-card-pro"><button class="x" onclick="closeModal()">×</button><div class="request-head"><div class="request-icon">🛒</div><div><span class="eyebrow">${x.ey}</span><h2>${x.title}</h2><p>${x.text}</p></div></div><form id="productRequestForm" onsubmit="submitProductRequest(event)"><label class="request-field full"><b>${x.product}</b><input name="productName" value="${esc(searched)}" placeholder="${x.example}" required></label><div class="request-two"><label class="request-field"><b>${x.qty}</b><input name="qty" type="number" min="1" value="1" required></label><label class="request-field"><b>${x.size}</b><input name="size" placeholder="${x.sizeEx}"></label></div><div class="request-two"><label class="request-field"><b>${x.name}</b><input name="customerName" placeholder="${x.name}"></label><label class="request-field"><b>${x.phone}</b><input name="phone" type="tel" placeholder="+998 90 123 45 67" required></label></div><label class="request-field full"><b>${x.comment}</b><textarea name="comment" maxlength="500" placeholder="${x.detail}"></textarea></label><label class="request-upload request-upload-pro"><span><b>${x.image}</b><small>JPG, PNG, WEBP — max 5 MB</small></span><span class="file-pick">${x.choose}</span><input id="requestImageInput" type="file" accept="image/jpeg,image/png,image/webp" onchange="prepareRequestImage(event)"></label><div id="requestImageStatus" class="location-status"></div><div class="request-submit-row"><button id="requestSubmit" class="btn primary" type="submit">➤ ${x.send}</button><span class="request-live-note">✓ ${x.live}</span></div><div id="requestStatus"></div></form></div>`)}
function prepareRequestImage(e){const file=e.target.files?.[0],st=$('#requestImageStatus');requestImage='';if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){st.textContent='Faqat JPG, PNG yoki WEBP rasm.';return}if(file.size>5*1024*1024){st.textContent='Rasm 8 MB dan katta bo‘lmasin.';return}const img=new Image(),rd=new FileReader();rd.onload=()=>{img.onload=()=>{const max=900,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);requestImage=c.toDataURL('image/jpeg',.78);st.textContent='Rasm tayyor.'};img.src=rd.result};rd.readAsDataURL(file)}
async function submitProductRequest(e){e.preventDefault();const f=e.currentTarget,fd=new FormData(f),btn=$('#requestSubmit'),st=$('#requestStatus');btn.disabled=true;st.textContent='So‘rov yuborilmoqda...';try{const r=await fetch('/api/product-requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productName:fd.get('productName'),qty:fd.get('qty'),size:fd.get('size'),customerName:fd.get('customerName'),phone:fd.get('phone'),comment:fd.get('comment'),image:requestImage})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Xatolik');st.innerHTML=`<div class="success-box"><b>So‘rovingiz qabul qilindi!</b><span>Raqam: ${esc(d.requestId)}</span><small>Tez orada siz bilan bog‘lanamiz.</small></div>`;f.reset();requestImage=''}catch(err){st.innerHTML=`<p class="error-text">${esc(err.message)}</p>`}finally{btn.disabled=false}}

