let lastTrackQuery={id:'',phone:''};
function webStatusLabel(status){const st=String(status||'').toLowerCase();const maps={uz:{new:'Yangi',accepted:'Qabul qilindi',preparing:'Tayyorlanmoqda',delivery:'Yetkazilmoqda',delivered:'Yetkazildi',completed:'Yakunlandi',done:'Yakunlandi',cancelled:'Bekor qilindi'},ru:{new:'Новый',accepted:'Принят',preparing:'Готовится',delivery:'Доставляется',delivered:'Доставлен',completed:'Завершён',done:'Завершён',cancelled:'Отменён'},en:{new:'New',accepted:'Accepted',preparing:'Preparing',delivery:'On the way',delivered:'Delivered',completed:'Completed',done:'Completed',cancelled:'Cancelled'}};return maps[lang]?.[st]||maps.uz[st]||status||''}
async function fetchTrackedOrder(id,phone,{silent=false}={}){const box=$('#trackResult');if(!box)return;if(!silent)box.innerHTML=`<p>${tr('checking')}</p>`;try{const r=await fetch(`/api/track/${encodeURIComponent(id)}?phone=${encodeURIComponent(phone)}`,{cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error);const completed=['completed','done'].includes(String(d.status||''));const source=d.completionSource==='customer'?tr('customer_confirmed'):d.completionSource==='admin'?tr('admin_confirmed'):'';const confirmBox=String(d.status)==='delivered'?`<div class="web-confirm-card"><b>${tr('confirm_question')}</b><div><button class="btn primary" onclick="confirmTrackedDelivery('${esc(id)}','${esc(phone)}',this)">${tr('confirm_yes')}</button><button class="btn ghost" onclick="showSiteToast('${tr('confirm_no')}')">${tr('confirm_no')}</button></div></div>`:'';box.innerHTML=`<div class="track-result"><h3>${completed&&source?esc(source):esc(webStatusLabel(d.status))}</h3><p><b>${esc(d.orderId)}</b></p>${source?`<span class="track-confirm-source">✓ ${esc(source)}</span>`:''}<p>${tr('area')}: ${esc(d.area)} • ${esc(d.deliverySlot)}</p>${d.address?`<p>${tr('address')}: ${esc(d.address)}</p>`:''}${d.payment?`<p>${tr('payment')}: ${esc(d.payment)}</p>`:''}<p>${(d.items||[]).map(x=>`${esc(x.name)} × ${x.qty}${x.price?` — ${money(Number(x.price)*Number(x.qty))}`:''}`).join('<br>')}</p><strong>${money(d.total)}</strong>${confirmBox}<small style="display:block;margin-top:8px;opacity:.65">${tr('live')}</small></div>`}catch(err){if(!silent)box.innerHTML=`<p class="error-text">${esc(err.message)}</p>`}}
async function confirmTrackedDelivery(id,phone,btn){if(btn){btn.disabled=true;btn.textContent=tr('confirming')}try{const r=await fetch(`/api/orders/${encodeURIComponent(id)}/confirm-delivery`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone,source:'web'})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Xatolik');showSiteToast('✓ '+tr('confirm_done'));await fetchTrackedOrder(id,phone)}catch(e){alert(e.message);if(btn){btn.disabled=false;btn.textContent=tr('confirm_yes')}}}
async function trackOrder(e){e.preventDefault();const fd=new FormData(e.currentTarget),id=fd.get('id').trim(),phone=fd.get('phone').trim();lastTrackQuery={id,phone};await fetchTrackedOrder(id,phone)}
function openCheckout(){if(!cart.length){alert(tr('cart_empty_alert'));return}closeCart();const areas=settings.delivery?.areas||[],slots=settings.delivery?.slots||[];$('#checkoutModal').innerHTML=`<div class="checkout-card"><button class="x" onclick="closeCheckout()">×</button><div class="checkout-head"><span class="eyebrow">${tr('free_delivery')}</span><h2>${tr('checkout_title')}</h2><p>📍 ${tr('checkout_desc')}</p></div><div class="checkout-grid"><form id="checkoutForm"><input name="name" placeholder="${tr('name')}" required><input name="phone" type="tel" placeholder="+998 90 123 45 67" required><select name="area" required><option value="">${tr('choose_area')}</option>${areas.map(a=>`<option>${esc(a)}</option>`).join('')}</select><textarea name="address" placeholder="${tr('street')}" required></textarea><select name="deliverySlot" required><option value="">${tr('choose_time')}</option>${slots.map(a=>`<option>${esc(a)}</option>`).join('')}</select><select name="payment" required><option value="">${tr('payment_type')}</option><option value="Naqd">${tr('cash')}</option><option value="Karta / terminal">${tr('card')}</option><option value="O‘tkazma">${tr('transfer')}</option></select><textarea name="comment" placeholder="${tr('comment')}"></textarea><input type="hidden" name="lat"><input type="hidden" name="lng"><input type="hidden" name="accuracy"><button class="location-btn" type="button" onclick="getLocation()">📍 ${tr('gps_again')}</button><div id="locationStatus" class="location-status"><b>📡 GPS...</b></div><div id="locationMapBox" class="checkout-location-map" hidden></div></form><aside><h3>${tr('order')}</h3>${cart.map(x=>{const p=products.find(p=>Number(p.id)===Number(x.id));return `<div class="summary-line"><span>${esc(nameOf(p))} × ${x.qty}</span><b>${money(p.price*x.qty)}</b></div>`}).join('')}<div class="summary-line"><span>${tr('discount')}</span><b>− ${money(promo.discount)}</b></div><div class="summary-line"><span>${tr('delivery')}</span><b class="free">${tr('free')}</b></div><div class="summary-line grand"><span>${tr('total')}</span><b>${money(total())}</b></div><button class="btn primary" id="orderSubmit" disabled onclick="submitOrder(event)">${tr('confirm_order')}</button><div id="checkoutStatus"></div></aside></div></div>`;$('#checkoutModal').classList.add('show');setOrderButtonAllowed(false);setTimeout(()=>getLocation(),250)}
function closeCheckout(){$('#checkoutModal').classList.remove('show')}
function pointInRing(lat,lng,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=Number(ring[i][0]),yi=Number(ring[i][1]),xj=Number(ring[j][0]),yj=Number(ring[j][1]);if(((yi>lat)!=(yj>lat))&&(lng<(xj-xi)*(lat-yi)/((yj-yi)||1e-12)+xi))inside=!inside}return inside}
function pointInGeometry(lat,lng,g){if(!g)return false;if(g.type==='Polygon')return pointInRing(lat,lng,g.coordinates[0])&&!g.coordinates.slice(1).some(r=>pointInRing(lat,lng,r));if(g.type==='MultiPolygon')return g.coordinates.some(poly=>pointInRing(lat,lng,poly[0])&&!poly.slice(1).some(r=>pointInRing(lat,lng,r)));return false}
function pointInFallback(lat,lng){return pointInRing(lat,lng,PARKENT_FALLBACK.map(([a,b])=>[b,a]))}
async function isInsideParkent(lat,lng){
 try{
  const r=await fetch(`/api/geo/parkent-check?lat=${encodeURIComponent(lat)}&lng=${encodeURIComponent(lng)}`,{cache:'no-store'});
  const d=await r.json();
  if(!r.ok)throw new Error(d.error||'Hududni tekshirib bo‘lmadi');
  return Boolean(d.inside);
 }catch(e){console.error('Parkent check:',e);return false}
}
function setOrderButtonAllowed(ok){const b=$('#orderSubmit');if(b){b.disabled=!ok;b.title=ok?'':'Buyurtma uchun GPS lokatsiya ±20 m aniqlikda majburiy'}}
function showCheckoutLocationMap(lat,lng,accuracy){
 const box=$('#locationMapBox');if(!box)return;box.hidden=false;
 const q=`${Number(lat).toFixed(6)},${Number(lng).toFixed(6)}`;
 box.innerHTML=`<iframe title="Sizning lokatsiyangiz" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.google.com/maps?q=${encodeURIComponent(q)}&z=17&output=embed"></iframe><div class="checkout-location-meta"><b>📍 Sizning aniqlangan joyingiz</b><span>${q}${Number.isFinite(Number(accuracy))?` • aniqlik ≈ ${Math.round(Number(accuracy))} m`:''}</span><a target="_blank" rel="noopener" href="https://maps.google.com/?q=${encodeURIComponent(q)}">Google Maps’da ochish ↗</a></div>`;
}
function clearCheckoutLocationMap(){const box=$('#locationMapBox');if(box){box.hidden=true;box.innerHTML=''}}
function getLocation(){
 const st=$('#locationStatus'),f=$('#checkoutForm');
 const fail=(title,detail='')=>{st.innerHTML=`<b>❌ ${title}</b>${detail?`<br>${detail}`:''}<br><button type="button" class="btn ghost" style="margin-top:8px" onclick="getLocation()">↻ Qayta urinish</button>`;setOrderButtonAllowed(false);clearCheckoutLocationMap()};
 if(!window.isSecureContext){fail('Lokatsiya uchun HTTPS kerak.','Saytni https://zarbuloq.uz orqali oching.');return}
 if(!navigator.geolocation){fail('Bu brauzer GPS lokatsiyani bermayapti.','Telegram ichki brauzerida bo‘lsangiz, menyudan Chrome/Safari’da ochib qayta urinib ko‘ring.');return}
 st.innerHTML='<b>📡 Lokatsiya avtomatik aniqlanmoqda...</b><br>Maqsad aniqlik: <b>±20 m</b>. Telefonni deraza yonida yoki ochiq joyda ushlab turing.';
 setOrderButtonAllowed(false);clearCheckoutLocationMap();
 if(f){f.elements.lat.value='';f.elements.lng.value='';if(f.elements.accuracy)f.elements.accuracy.value=''}
 let best=null,count=0,finished=false,watchId=null,timer=null;
 const finish=async()=>{
  if(finished)return;finished=true;if(timer)clearTimeout(timer);if(watchId!==null)navigator.geolocation.clearWatch(watchId);
  if(!best){fail('Lokatsiya olinmadi.','Telefon sozlamalarida Location/GPS va brauzer uchun lokatsiya ruxsatini yoqing. Telegram ichida ochilgan bo‘lsa Chrome/Safari’da oching.');return}
  const {lat,lng,accuracy}=best;showCheckoutLocationMap(lat,lng,accuracy);
  if(Number(accuracy)>20){fail(`GPS aniqligi yetarli emas: ±${Math.round(accuracy)} m.`,'Buyurtma uchun ±20 m yoki yaxshiroq aniqlik talab qilinadi. Ochiqroq joyda GPS’ni qayta aniqlang.');return}
  f.elements.lat.value=lat;f.elements.lng.value=lng;if(f.elements.accuracy)f.elements.accuracy.value=accuracy;
  st.innerHTML='<b>📍 Lokatsiya olindi.</b><br>Parkent tumani chegarasi tekshirilmoqda...';
  try{
   const inside=await isInsideParkent(lat,lng);
   if(!inside){f.elements.lat.value='';f.elements.lng.value='';if(f.elements.accuracy)f.elements.accuracy.value='';fail('Lokatsiya Parkent tumani hududidan tashqarida.','Xaritadagi nuqta noto‘g‘ri bo‘lsa GPS’ni qayta aniqlang.');showCheckoutLocationMap(lat,lng,accuracy);return}
   st.innerHTML=`<b>✅ Parkent tumani tasdiqlandi.</b><br>GPS aniqligi: <b>±${Math.round(accuracy)} m</b>. Buyurtma berishingiz mumkin.`;setOrderButtonAllowed(true)
  }catch(e){fail('Hududni tekshirishda internet xatosi.','Qayta urinib ko‘ring.');}
 };
 const accept=pos=>{const c=pos?.coords;if(!c)return;const accuracy=Number(c.accuracy||9999);if(!best||accuracy<best.accuracy){best={lat:Number(c.latitude),lng:Number(c.longitude),accuracy};showCheckoutLocationMap(best.lat,best.lng,best.accuracy);st.innerHTML=`<b>📍 GPS aniqlashtirilmoqda...</b><br>Hozirgi aniqlik: ±${Math.round(best.accuracy)} m`};count++;if(accuracy<=20)finish();else if(count>=10&&best)finish()};
 const onerr=err=>{if(best){finish();return}const msg=err?.code===1?'Lokatsiyaga ruxsat berilmagan.':err?.code===2?'GPS signal topilmadi.':'Lokatsiya olish vaqti tugadi.';fail(msg,'Telefon Location/GPS ruxsatini tekshiring. Telegram ichida bo‘lsa Chrome/Safari’da ochib ko‘ring.')};
 try{watchId=navigator.geolocation.watchPosition(accept,onerr,{enableHighAccuracy:true,timeout:15000,maximumAge:0});timer=setTimeout(()=>{if(best)finish();else navigator.geolocation.getCurrentPosition(p=>{accept(p);finish()},onerr,{enableHighAccuracy:true,timeout:10000,maximumAge:0})},30000)}catch(e){fail('GPS ishga tushmadi.','Brauzer lokatsiya ruxsatini tekshiring.')}
}
function receiptPaymentText(payment){const p=String(payment||'Naqd').trim();if(p==='Karta / terminal')return 'Mahsulot yetkazilgandan keyin<br><b>karta terminal orqali to‘lanadi</b>';if(p==='O‘tkazma')return 'To‘lov<br><b>bank o‘tkazmasi orqali amalga oshiriladi</b>';return 'Mahsulot yetkazilgandan keyin<br><b>Naqd to‘lanadi</b>'}
function receiptStatusLabel(status,order={}){const st=String(status||'new').toLowerCase(),src=String(order?.completionSource||(order?.customerConfirmed?'customer':order?.adminConfirmed?'admin':'')).toLowerCase();if(['completed','done'].includes(st)&&src==='customer')return tr('customer_confirmed').toUpperCase();if(['completed','done'].includes(st)&&src==='admin')return tr('admin_confirmed').toUpperCase();return webStatusLabel(st).toUpperCase()}
function closeReceipt(){const m=$('#receiptModal');if(m)m.classList.remove('show')}
async function ensureReceiptCanvas(){if(window.html2canvas)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js';s.onload=resolve;s.onerror=()=>reject(new Error('Rasm moduli yuklanmadi'));document.head.appendChild(s)})}
async function saveReceiptImage(){const card=document.querySelector('#receiptModal .receipt-card');if(!card)return;try{await ensureReceiptCanvas();const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff',ignoreElements:el=>el.classList&&el.classList.contains('receipt-x')});canvas.toBlob(blob=>{if(!blob)return;const a=document.createElement('a');a.href=URL.createObjectURL(blob);const id=(card.querySelector('.receipt-title small')?.textContent||'CHEK').replace(/[^a-zA-Z0-9_-]/g,'_');a.download=`ZARBULOQ_${id}.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500);const old=document.querySelector('.receipt-saved-toast');if(old)old.remove();const t=document.createElement('div');t.className='receipt-saved-toast';t.textContent='✓ Chek rasm sifatida saqlandi';document.body.appendChild(t);setTimeout(()=>t.remove(),2500)},'image/png')}catch(e){alert('Chekni rasm sifatida saqlashda xatolik: '+e.message)}}
function printReceipt(){const card=document.querySelector('#receiptModal .receipt-card');if(!card)return;const w=window.open('','_blank','width=620,height=900');if(!w)return;w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Elektron chek</title><link rel="stylesheet" href="/style.css"></head><body style="background:#fff;padding:20px">${card.outerHTML}<script>setTimeout(()=>window.print(),400)<\/script></body></html>`);w.document.close()}
function showReceipt(order){const m=$('#receiptModal');if(!m||!order)return;const items=Array.isArray(order.items)?order.items:[];const created=new Date(order.createdAt||Date.now());const date=created.toLocaleDateString('uz-UZ');const time=created.toLocaleTimeString('uz-UZ',{hour:'2-digit',minute:'2-digit'});const verifyUrl=`${location.origin}/#track`;const qr=`https://quickchart.io/qr?size=150&text=${encodeURIComponent(verifyUrl+'?order='+order.orderId)}`;m.innerHTML=`<div class="receipt-shell"><div class="receipt-card"><button class="receipt-x" onclick="closeReceipt()">×</button><div class="receipt-hero"><img src="/logo.png" alt="ZARBULOQ.UZ"><div><b>ZARBULOQ.UZ</b><span>IMOM OTA BARAKA</span><small>Tabiatdan sizning uyingizgacha</small></div></div><div class="receipt-title">ELEKTRON CHEK<small>№ ${esc(order.orderId)}</small></div><div class="receipt-meta"><span>📅 ${esc(date)} &nbsp; ${esc(time)}</span><span>👤 ${esc(order.customer?.name||'')}</span><span>☎ ${esc(order.customer?.phone||'')}</span><span>📍 ${esc(order.customer?.area||'')}${order.customer?.address?' • '+esc(order.customer.address):''}</span></div><div class="receipt-items">${items.map(it=>`<div class="receipt-item"><div><b>${esc(it.name||'Mahsulot')}</b><small>${Number(it.qty||0)} × ${money(Number(it.price||0))}</small></div><strong>${money(Number(it.price||0)*Number(it.qty||0))}</strong></div>`).join('')}</div><div class="receipt-totals"><div><span>Oraliq summa</span><b>${money(order.subtotal||order.total||0)}</b></div><div><span>Yetkazib berish</span><b>0 so‘m</b></div><div><span>Chegirma</span><b>${money(order.discount||0)}</b></div><div class="grand"><span>JAMI</span><b>${money(order.total||0)}</b></div></div><div class="receipt-payment receipt-payment-v14"><span class="receipt-pay-note"><i>💵</i><span>${receiptPaymentText(order.customer?.payment)}</span></span><span class="receipt-order-state"><i>📋</i><span>Holat: <b class="receipt-status">◷ ${receiptStatusLabel(order.status,order)}</b></span></span></div><em>“Soflik va baraka har doim siz bilan!”</em><div class="receipt-qr"><img src="${qr}" alt="QR"><div><b>Chekni tekshirish</b><small>zarbuloq.uz</small></div></div><div class="receipt-actions"><button class="btn primary" onclick="saveReceiptImage()">📥 Galereyaga saqlash</button><button class="btn" onclick="printReceipt()">📄 PDF / Chop etish</button><button class="btn" onclick="closeReceipt()">Yopish</button></div></div></div>`;closeCheckout();m.classList.add('show')}
async function submitOrder(e){e.preventDefault();const f=$('#checkoutForm');if(!f.reportValidity())return;const btn=$('#orderSubmit'),status=$('#checkoutStatus'),fd=new FormData(f);const lat=Number(fd.get('lat')),lng=Number(fd.get('lng')),accuracy=Number(fd.get('accuracy'));if(!Number.isFinite(lat)||!Number.isFinite(lng)||!Number.isFinite(accuracy)||accuracy>20){status.innerHTML='<p class="error-text">📍 Buyurtma uchun GPS lokatsiya majburiy va aniqlik ±20 m yoki yaxshiroq bo‘lishi kerak. GPS’ni qayta aniqlang.</p>';setOrderButtonAllowed(false);return}btn.disabled=true;status.textContent='Buyurtma yuborilmoqda...';const order={source:'web',customer:{name:fd.get('name'),phone:fd.get('phone'),area:fd.get('area'),address:fd.get('address'),deliverySlot:fd.get('deliverySlot'),payment:fd.get('payment'),comment:fd.get('comment'),lat:fd.get('lat'),lng:fd.get('lng'),accuracy:fd.get('accuracy')},items:cart.map(x=>({id:x.id,qty:x.qty})),promoCode:promo.code,language:lang};try{const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(order)});const d=await r.json();if(!r.ok&&!d.saved)throw new Error(d.error||'Xatolik');const receipt=d.order||{orderId:d.orderId,createdAt:new Date().toISOString(),status:'new',customer:order.customer,items:cart.map(x=>{const p=products.find(p=>Number(p.id)===Number(x.id));return {id:x.id,name:nameOf(p),price:Number(p?.price||0),qty:x.qty}}),subtotal:total()+promo.discount,discount:promo.discount,total:d.total??total()};cart=[];promo={code:'',discount:0};saveCart();renderCart();renderProducts();showReceipt(receipt)}catch(err){status.innerHTML=`<p class="error-text">${esc(err.message)}</p>`}finally{btn.disabled=false}}


function openSiteChat(){const p=$('#siteChatPopup');if(!p)return;p.classList.add('open');p.setAttribute('aria-hidden','false');loadSiteChat().finally(()=>{prefillChatIdentity();updateChatIdentityState();setTimeout(()=>{const n=$('#chatName'),ph=$('#chatPhone');if(!String(n?.value||'').trim())n?.focus();else if(!validChatPhone(ph?.value||''))ph?.focus();else $('#siteChatInput')?.focus()},80)})}
function closeSiteChat(){const p=$('#siteChatPopup');if(!p)return;p.classList.remove('open');p.setAttribute('aria-hidden','true')}
function toggleSiteChat(){const p=$('#siteChatPopup');if(!p)return;p.classList.contains('open')?closeSiteChat():openSiteChat()}
function chatTime(v){try{return new Date(v).toLocaleTimeString('uz-UZ',{hour:'2-digit',minute:'2-digit'})}catch{return ''}}
function renderSiteChat(chat){const box=$('#siteChatMessages');if(!box)return;const msgs=chat?.messages||[];box.innerHTML=msgs.length?msgs.map(m=>`<div class="chat-msg ${m.from==='admin'?'admin':'customer'}">${esc(m.text)}<small>${m.from==='admin'?'Admin':tr('you')} • ${chatTime(m.createdAt)}</small></div>`).join(''):`<div class="chat-empty">${tr('chat_empty')}</div>`;box.scrollTop=box.scrollHeight}
async function loadSiteChat(){try{const r=await fetch('/api/chat/'+encodeURIComponent(siteChatId),{cache:'no-store'}),d=await r.json();if(r.ok){renderSiteChat(d);if($('#chatName')&&!$('#chatName').value&&d.name)$('#chatName').value=d.name;if($('#chatPhone')&&!$('#chatPhone').value&&d.phone)$('#chatPhone').value=d.phone;updateChatIdentityState()}}catch(e){console.error('Chat load',e)}}
function validChatPhone(v){const d=String(v||'').replace(/\D/g,'');return /^(998)?\d{9}$/.test(d)}
function chatIdentity(){return {name:String($('#chatName')?.value||'').trim(),phone:String($('#chatPhone')?.value||'').trim()}}
function prefillChatIdentity(){try{const saved=JSON.parse(localStorage.getItem('zarbuloq_customer_identity')||'{}');const n=$('#chatName'),p=$('#chatPhone');if(n&&!n.value&&saved.name)n.value=saved.name;if(p&&!p.value&&saved.phone)p.value=saved.phone}catch{}}
function updateChatIdentityState(){const {name,phone}=chatIdentity(),ok=name.length>=2&&validChatPhone(phone),inp=$('#siteChatInput'),btn=document.querySelector('.site-chat-form button'),hint=$('#chatIdentityHint');if(inp)inp.disabled=!ok;if(btn)btn.disabled=!ok;if(hint){hint.textContent=ok?'✓ OK':tr('chat_identity');hint.classList.toggle('ok',ok)}return ok}
document.addEventListener('input',e=>{if(e.target?.id==='chatName'||e.target?.id==='chatPhone')updateChatIdentityState()})
async function sendSiteChat(e){e.preventDefault();const inp=$('#siteChatInput'),text=inp.value.trim(),identity=chatIdentity();if(!updateChatIdentityState()){alert('Chat yozish uchun ism va to‘g‘ri telefon raqamini kiriting.');return}if(!text)return;const btn=e.currentTarget.querySelector('button');btn.disabled=true;try{const r=await fetch('/api/chat/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId:siteChatId,name:identity.name,phone:identity.phone,message:text})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Xatolik');localStorage.setItem('zarbuloq_customer_identity',JSON.stringify(identity));inp.value='';renderSiteChat(d.chat)}catch(err){alert(err.message)}finally{updateChatIdentityState()}}

let realtimeSource=null,realtimeTimer=null,realtimeReloading=false,realtimeLastEvent=Date.now();
function initRealtime(){
 if(!window.EventSource||realtimeSource)return;
 realtimeSource=new EventSource('/api/events');
 realtimeSource.addEventListener('update',()=>{
  realtimeLastEvent=Date.now();
  clearTimeout(realtimeTimer);
  realtimeTimer=setTimeout(refreshRealtimeStore,180);
  loadSiteChat();
 });
 realtimeSource.onopen=()=>{realtimeLastEvent=Date.now()};
 realtimeSource.onerror=()=>{}; // EventSource reconnects automatically
}
async function refreshRealtimeStore(){
 if(realtimeReloading)return;
 realtimeReloading=true;
 try{
  await loadCatalog();
  if(lastTrackQuery && $('#trackingPanel')?.classList.contains('open')) await fetchTrackedOrder(lastTrackQuery.id,lastTrackQuery.phone,{silent:true});
 }finally{realtimeReloading=false}
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeCheckout();closeCart();closeSiteChat()}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
